const timeline=document.querySelector('#timeline');
chapters.forEach((c,i)=>{const b=document.createElement('button');b.type='button';b.role='tab';b.dataset.index=i;b.setAttribute('aria-selected',i===0?'true':'false');b.innerHTML=`<small>${c.kind} · ${c.time}</small><strong>${c.name}</strong>`;timeline.appendChild(b)});
const stage=document.querySelector('#timeStage');
function showChapter(index){const c=chapters[index];document.querySelectorAll('#timeline button').forEach((b,i)=>b.setAttribute('aria-selected',i===index?'true':'false'));document.querySelector('#chapterLabel').textContent=`CAPÍTULO ${String(index+1).padStart(2,'0')} / ${chapters.length}`;document.querySelector('#eraTime').textContent=c.time;document.querySelector('#eraName').textContent=c.name;document.querySelector('#eraTagline').textContent=c.tag;document.querySelector('#factTitle').textContent=c.fact;document.querySelector('#factDetail').textContent=c.detail;stage.style.setProperty('--sky1',c.colors[0]);stage.style.setProperty('--sky2',c.colors[1]);stage.style.setProperty('--ground',c.colors[2]);stage.style.setProperty('--landback',c.colors[3]);stage.style.setProperty('--landfront',c.colors[4]);stage.style.setProperty('--sun',c.colors[5]);stage.style.setProperty('--shape',c.shape);document.querySelector('#factCard').setAttribute('aria-expanded','false')}
timeline.addEventListener('click',e=>{const b=e.target.closest('button');if(b){showChapter(Number(b.dataset.index));b.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}});
document.querySelector('#factCard').addEventListener('click',e=>{const b=e.currentTarget;b.setAttribute('aria-expanded',b.getAttribute('aria-expanded')!=='true')});

const clueText=['La marca tiene tres dedos largos y termina en garras. Es la huella de un terópodo bípedo.','La distancia entre huellas indica una marcha tranquila, no una persecución. El animal mediría varios metros.','Las marcas terminan en una antigua orilla. Quizá buscaba agua o seguía a otra criatura.'];
document.querySelectorAll('.clue').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.clue').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('#clueReader').textContent=clueText[Number(b.dataset.clue)]}));
document.querySelector('#checkAnswer').addEventListener('click',()=>{const selected=document.querySelector('input[name=answer]:checked');const result=document.querySelector('#result');if(!selected){result.className='result wrong';result.textContent='Elige una hipótesis antes de comprobarla.';return}const ok=selected.value==='theropod';result.className=`result ${ok?'correct':'wrong'}`;result.textContent=ok?'La evidencia coincide. La forma tridáctila y la zancada corresponden a un terópodo mediano. Aún no podemos conocer la especie exacta.':'Esa hipótesis no explica la forma tridáctila. Revisa la huella: la anatomía importa más que el tamaño.'});

document.querySelectorAll('.pulse-chart button').forEach(b=>{const show=()=>document.querySelector('#chartTooltip').textContent=b.dataset.label;b.addEventListener('mouseenter',show);b.addEventListener('focus',show)});

let audioContext,oscillator,gain;
document.querySelector('#soundToggle').addEventListener('click',async e=>{const btn=e.currentTarget;const on=btn.getAttribute('aria-pressed')==='true';if(on){gain?.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+.4);setTimeout(()=>audioContext?.close(),500);btn.setAttribute('aria-pressed','false');return}audioContext=new AudioContext();oscillator=audioContext.createOscillator();gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.value=82;gain.gain.value=.0001;oscillator.connect(gain).connect(audioContext.destination);oscillator.start();gain.gain.exponentialRampToValueAtTime(.018,audioContext.currentTime+1);btn.setAttribute('aria-pressed','true')});

showChapter(0);
